using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AuraEffects", menuName = "Data/Battle/Effects/Enemy/AuraEffects")]
public class AuraEffects : Effect
{
	private const string auraEffectStayActiveID = "AuraEffectStayActive";

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return base.GetEffectDescription(amount, effectOwner) + "\n" + base.localizationManager.GetLocalizedString("AuraEffectStayActive");
	}
}
